18	/**
19	 * Maps Owner & OwnerDto using Mapstruct
20	 */
21	@Mapper(uses = PetMapper.class)
22	public interface OwnerMapper {
23	
24	    @Mapping(target = "displayName", source = "owner", qualifiedByName = "toDisplayName")
25	    @Mapping(target = "telephoneDisplay", source = "owner", qualifiedByName = "toTelephoneDisplay")
26	    @Mapping(target = "initials", source = "owner", qualifiedByName = "toInitials")
27	    @Mapping(target = "membershipNumber", source = "owner", qualifiedByName = "toMembershipNumber")
28	    @Mapping(target = "checkDigit", source = "owner", qualifiedByName = "toCheckDigit")
29	    @Mapping(target = "membershipPoints", source = "owner", qualifiedByName = "toMembershipPoints")
30	    @Mapping(target = "membershipLevel", source = "owner", qualifiedByName = "toMembershipLevel")
31	    @Mapping(target = "locality", source = "owner", qualifiedByName = "toLocality")
32	    @Mapping(target = "contactPreference", source = "owner", qualifiedByName = "toContactPreference")
33	    @Mapping(target = "identityKey", source = "owner", qualifiedByName = "toIdentityKey")
34	    @Mapping(target = "ageBand", source = "owner", qualifiedByName = "toAgeBand")
35	    OwnerDto toOwnerDto(Owner owner);
36	
37	    /**
38	     * Derives the owner's {@code ageBand} from its {@code birthDate}, computed against the
39	     * {@code registrationDate}: {@code 'MINOR'} when the owner is under 18 on the registration date,
40	     * {@code 'ADULT'} from 18 up to and including 64, and {@code 'SENIOR'} at 65 or over. Returns
41	     * {@code null} when either the birth date or the registration date is absent.
42	     */
43	    @Named("toAgeBand")
44	    default OwnerDto.AgeBandEnum toAgeBand(Owner owner) {
45	        if (owner == null || owner.getBirthDate() == null || owner.getRegistrationDate() == null) {
46	            return null;
47	        }
48	        int age = java.time.Period.between(owner.getBirthDate(), owner.getRegistrationDate()).getYears();
49	        if (age < 18) {
50	            return OwnerDto.AgeBandEnum.MINOR;
51	        }
52	        if (age < 65) {
53	            return OwnerDto.AgeBandEnum.ADULT;
54	        }
55	        return OwnerDto.AgeBandEnum.SENIOR;
56	    }
57	
58	    /**
59	     * Derives the owner's duplicate-detection {@code identityKey}: the single key that consolidates
60	     * the former separate telephone, email and household checks. It is the owner's normalized
61	     * telephone, its email (lower-cased and trimmed, or the empty string when absent) and its
62	     * household identifier (or the empty string when absent), joined in that order by {@code '|'}.
63	     * Because the telephone is part of the key, two members of the same household with different
64	     * telephones have different identity keys; only an exact full-key match is a duplicate.
65	     */
66	    @Named("toIdentityKey")
67	    default String toIdentityKey(Owner owner) {
68	        if (owner == null) {
69	            return null;
70	        }
71	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone().trim();
72	        String email = owner.getEmail() == null ? "" : owner.getEmail().trim().toLowerCase(java.util.Locale.ROOT);
73	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
74	        return telephone + "|" + email + "|" + householdId;
75	    }
76	
77	    /**
78	     * Derives the owner's preferred contact channel: {@code 'EMAIL'} when the owner has a non-blank
79	     * email, otherwise {@code 'PHONE'}.
80	     */
81	    @Named("toContactPreference")
82	    default String toContactPreference(Owner owner) {
83	        if (owner == null) {
84	            return null;
85	        }
86	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
87	        return hasEmail ? "EMAIL" : "PHONE";
88	    }
89	
90	    /**
91	     * Fixed city-to-region table used as the fallback for deriving an owner's locality.
92	     */
93	    java.util.Map<String, String> CITY_REGION = java.util.Map.of(
94	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
95	
96	    /**
97	     * Fixed region-to-postcode range table: each region admits an inclusive 4-digit range
98	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). Used to derive an
99	     * owner's locality from its postcode in preference to its city.
100	     */
101	    java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
102	        "NSW", new int[] {2000, 2099},
103	        "VIC", new int[] {3000, 3099},
104	        "QLD", new int[] {4000, 4099});
105	
106	    /**
107	     * Derives the owner's canonical region, the {@code REGION} component of its {@code customerCode}.
108	     * The postcode takes precedence: when the owner has a well-formed 4-digit postcode that falls
109	     * within a known region's range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD
110	     * 4000-4099}), that region is returned. Otherwise the region is looked up from the fixed
111	     * city-to-region table ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}),
112	     * yielding {@code 'UNKNOWN'} when the city is not in the table. Preferring the postcode returns
113	     * the same region for known cities but disambiguates cities that share a name.
114	     */
115	    default String toRegion(Owner owner) {
116	        if (owner == null) {
117	            return null;
118	        }
119	        String regionByPostcode = regionForPostcode(owner.getPostcode());
120	        if (regionByPostcode != null) {
121	            return regionByPostcode;
122	        }
123	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
124	    }
125	
126	    /**
127	     * Derives the owner's locality as the {@code REGION} component of its region-and-hash
128	     * {@code customerCode} (the prefix before the first {@code '-'}). The locality therefore shares
129	     * the customer code's identity rather than being computed independently. When the customer code
130	     * is absent the region is derived directly from the owner's postcode and city via
131	     * {@link #toRegion(Owner)}.
132	     */
133	    @Named("toLocality")
134	    default String toLocality(Owner owner) {
135	        if (owner == null) {
136	            return null;
137	        }
138	        String customerCode = owner.getCustomerCode();
139	        if (customerCode != null) {
140	            int dash = customerCode.indexOf('-');
141	            if (dash >= 0) {
142	                return customerCode.substring(0, dash);
143	            }
144	        }
145	        return toRegion(owner);
146	    }
147	
148	    /**
149	     * Returns the region whose inclusive postcode range contains the given 4-digit postcode, or
150	     * {@code null} when the postcode is absent, malformed, or in no known range.
151	     */
152	    private static String regionForPostcode(String postcode) {
153	        if (postcode == null || !postcode.matches("\\d{4}")) {
154	            return null;
155	        }
156	        int value = Integer.parseInt(postcode);
157	        for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
158	            int[] range = entry.getValue();
159	            if (value >= range[0] && value <= range[1]) {
160	                return entry.getKey();
161	            }
162	        }
163	        return null;
164	    }
165	
166	    /**
167	     * Formats the owner's stored names as {@code 'LastName, FirstName'}.
168	     */
169	    @Named("toDisplayName")
170	    default String toDisplayName(Owner owner) {
171	        if (owner == null) {
172	            return null;
173	        }
174	        return owner.getLastName() + ", " + owner.getFirstName();
175	    }
176	
177	    /**
178	     * Formats the owner's stored E.164 {@code telephone} for humans: the country code, a space, then
179	     * the national digits grouped in threes, e.g. {@code "+61412345678"} becomes
180	     * {@code "+61 412 345 678"}. The country code is a single {@code '1'} for NANP ({@code +1}) numbers
181	     * and two digits otherwise (covering the {@code +61} numbers the app stores). Returns the value
182	     * unchanged when it is absent or not a well-formed E.164 number, leaving raw {@code telephone}
183	     * untouched.
184	     */
185	    @Named("toTelephoneDisplay")
186	    default String toTelephoneDisplay(Owner owner) {
187	        if (owner == null) {
188	            return null;
189	        }
190	        String telephone = owner.getTelephone();
191	        if (telephone == null || !telephone.matches("\\+[0-9]{8,15}")) {
192	            return telephone;
193	        }
194	        String digits = telephone.substring(1);
195	        int countryCodeLength = digits.startsWith("1") ? 1 : 2;
196	        String countryCode = digits.substring(0, countryCodeLength);
197	        String national = digits.substring(countryCodeLength);
198	        StringBuilder sb = new StringBuilder("+").append(countryCode);
199	        for (int i = 0; i < national.length(); i++) {
200	            if (i % 3 == 0) {
201	                sb.append(' ');
202	            }
203	            sb.append(national.charAt(i));
204	        }
205	        return sb.toString();
206	    }
207	
208	    /**
209	     * Returns the owner's initials as the upper-cased first letters of firstName and lastName,
210	     * dot-separated with a trailing dot, e.g. {@code 'J.S.'}.
211	     */
212	    @Named("toInitials")
213	    default String toInitials(Owner owner) {
214	        if (owner == null) {
215	            return null;
216	        }
217	        return initial(owner.getFirstName()) + initial(owner.getLastName());
218	    }
219	
220	    /**
221	     * Formats the owner's membership number as {@code '<customerCode>-M<YY>'}, where {@code YY} is
222	     * the last two digits of the {@code registrationDate} year, e.g. {@code 'NSW-1A2B3C4D-M26'}. Returns
